24	/// Guard that holds a session lock file and removes it on drop.
25	struct SessionLock {
26	    path: PathBuf,
27	}
28	
29	impl SessionLock {
30	    fn acquire(cwd: &Path) -> Result<Self, String> {
31	        let lock_path = cwd.join("baro.lock");
32	
33	        if lock_path.exists() {
34	            if let Ok(contents) = std::fs::read_to_string(&lock_path) {
35	                if let Ok(pid) = contents.trim().parse::<u32>() {
36	                    if is_process_alive(pid) {
37	                        return Err(
38	                            "Another baro session is active in this directory. Multiple sessions per project coming soon.".to_string()
39	                        );
40	                    }
41	                }
42	            }
43	            // Stale lock file — overwrite below
44	        }
45	
46	        std::fs::write(&lock_path, std::process::id().to_string())
47	            .map_err(|e| format!("Failed to create lock file: {}", e))?;
48	
49	        Ok(SessionLock { path: lock_path })
50	    }
51	}
52	
53	impl Drop for SessionLock {
54	    fn drop(&mut self) {
55	        let _ = std::fs::remove_file(&self.path);
56	    }
57	}
