60	fn is_process_alive(pid: u32) -> bool {
61	    std::process::Command::new("kill")
62	        .args(["-0", &pid.to_string()])
63	        .stdout(std::process::Stdio::null())
64	        .stderr(std::process::Stdio::null())
65	        .status()
66	        .map(|s| s.success())
67	        .unwrap_or(false)
68	}
