280	#[tokio::main]
281	async fn main() -> Result<(), Box<dyn std::error::Error>> {
282	    let cli = Cli::parse();
283	
284	    // Resolve cwd early so we can acquire the session lock before entering the TUI
285	    let cwd = std::fs::canonicalize(&cli.cwd)?;
286	
287	    // Acquire session lock — prints error and exits if another session is active
288	    let _lock = match SessionLock::acquire(&cwd) {
289	        Ok(lock) => lock,
290	        Err(msg) => {
291	            eprintln!("{}", msg);
292	            std::process::exit(1);
293	        }
294	    };
295	
296	    let mut writer = open_terminal_writer()?;
297	    enable_raw_mode()?;
298	    execute!(writer, EnterAlternateScreen)?;
299	    execute!(writer, Clear(ClearType::All))?;
300	    execute!(writer, Clear(ClearType::Purge))?;
301	    let backend = CrosstermBackend::new(writer);
302	    let mut terminal = Terminal::new(backend)?;
303	
304	    let is_dry_run = cli.dry_run;
305	    let result = run_app(&mut terminal, cli).await;
306	
307	    disable_raw_mode()?;
308	    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
309	    terminal.show_cursor()?;
310	    terminal.backend_mut().flush()?;
311	
312	    // _lock is dropped here, removing baro.lock
313	
314	    if let Err(err) = result {
315	        eprintln!("Error: {}", err);
316	        std::process::exit(1);
317	    }
318	
319	    // Print dry-run message after TUI exits
320	    if is_dry_run {
321	        let prd_path = cwd.join("prd.json");
322	        if prd_path.exists() {
323	            println!("\x1b[32m\u{2713}\x1b[0m Dry run complete \u{2014} plan saved to prd.json");
324	            println!("  Run \x1b[1mbaro --resume\x1b[0m to execute the saved plan.");
325	        }
326	    }
327	
328	    Ok(())
329	}
