331	async fn run_app(
332	    terminal: &mut Terminal<CrosstermBackend<Box<dyn Write>>>,
333	    cli: Cli,
334	) -> Result<(), Box<dyn std::error::Error>> {
335	    let mut app = App::new();
336	    let cwd = std::fs::canonicalize(&cli.cwd)?;
337	
338	    // Load .barorc config (defaults if not found)
339	    let rc = config::load_config(&cwd);
340	
341	    // Apply config defaults, then CLI overrides
342	    app.parallel_limit = rc.parallel.unwrap_or(0);
343	    app.timeout_secs = rc.timeout.unwrap_or(600);
344	    app.skip_context = rc.skip_context.unwrap_or(false);
345	
346	    app.planner = match rc.planner.as_deref() {
347	        Some("openai") => Planner::OpenAI,
348	        _ => Planner::Claude,
349	    };
350	
351	    match rc.model.as_deref() {
352	        Some("opus") | Some("sonnet") | Some("haiku") => {
353	            app.override_model = rc.model.clone();
354	            app.model_routing = false;
355	        }
356	        _ => {} // "routed" or None = keep defaults
357	    }
358	
359	    // CLI args override config
360	    if cli.parallel != 0 { app.parallel_limit = cli.parallel; }
361	    if cli.timeout != 600 { app.timeout_secs = cli.timeout; }
362	    if cli.skip_context { app.skip_context = true; }
363	    if rc.dry_run == Some(true) { app.dry_run = true; }
364	    if cli.dry_run { app.dry_run = true; }
365	
366	    if cli.planner != "claude" {
367	        app.planner = match cli.planner.as_str() {
368	            "openai" => Planner::OpenAI,
369	            _ => Planner::Claude,
370	        };
371	    }
372	
373	    if let Some(ref model) = cli.model {
374	        app.override_model = Some(model.clone());
375	        app.model_routing = false;
376	    } else if cli.no_model_routing {
377	        app.override_model = Some("opus".to_string());
378	        app.model_routing = false;
379	    }
380	
381	    // Critic + Surgeon (with LLM) are now ON by default. The historical
382	    // --with-critic / --with-surgeon / --surgeon-use-llm flags are still
383	    // accepted (hidden) for backwards compatibility; --no-* flags opt out.
384	    if cli.no_critic {
385	        app.with_critic = false;
386	    } else {
387	        app.with_critic = true;
388	    }
389	    if let Some(ref m) = cli.critic_model {
390	        app.critic_model = Some(m.clone());
391	    }
392	    if cli.no_librarian {
393	        app.with_librarian = false;
394	    }
395	    if cli.no_sentry {
396	        app.with_sentry = false;
397	    }
398	    if cli.no_surgeon {
399	        app.with_surgeon = false;
400	    } else {
401	        app.with_surgeon = true;
402	    }
403	    if cli.no_surgeon_llm {
404	        app.surgeon_use_llm = false;
405	    } else {
406	        app.surgeon_use_llm = true;
407	    }
408	    if let Some(ref m) = cli.surgeon_model {
409	        app.surgeon_model = Some(m.clone());
410	    }
411	
412	    let (tx, mut rx) = mpsc::channel::<AppEvent>(256);
413	
414	    // Resume detection: check for existing prd.json with incomplete stories
415	    let prd_path = cwd.join("prd.json");
416	    let mut entered_resume = false;
417	    if prd_path.exists() {
418	        if let Ok(prd_contents) = std::fs::read_to_string(&prd_path) {
419	            if let Ok(prd) = serde_json::from_str::<executor::PrdFile>(&prd_contents) {
420	                let has_incomplete = prd.user_stories.iter().any(|s| !s.passes);
421	                if cli.resume || (has_incomplete && cli.goal.is_none()) {
422	                    app.is_resume = true;
423	                    app.project = prd.project.clone();
424	                    app.branch_name = prd.branch_name.clone();
425	                    app.description = prd.description.clone();
426	                    let stories: Vec<ReviewStory> = prd.user_stories.iter().map(|s| ReviewStory {
427	                        id: s.id.clone(),
428	                        title: s.title.clone(),
429	                        description: s.description.clone(),
430	                        depends_on: s.depends_on.clone(),
431	                        completed: s.passes,
432	                        model: s.model.clone(),
433	                    }).collect();
434	                    app.show_review(stories);
435	                    entered_resume = true;
436	                }
437	            }
438	        }
439	    }
440	
441	    // If goal provided via CLI (and not resuming), skip welcome and start context/planning
442	    if !entered_resume {
443	        if let Some(goal) = cli.goal {
444	            app.goal_input = goal;
445	            if app.skip_context {
446	                app.start_planning();
447	                spawn_planner(&app, &cwd, tx.clone());
448	            } else {
449	                let claude_md_path = cwd.join("CLAUDE.md");
450	                if claude_md_path.exists() {
451	                    if let Ok(content) = std::fs::read_to_string(&claude_md_path) {
452	                        app.claude_md_content = Some(content);
453	                    }
454	                    app.start_planning();
455	                    spawn_planner(&app, &cwd, tx.clone());
456	                } else {
457	                    app.start_context();
458	                    spawn_context_builder(&cwd, tx.clone());
459	                }
460	            }
461	        }
462	    }
463	
464	    // Keyboard input from /dev/tty
465	    let tx_key = tx.clone();
466	    std::thread::spawn(move || loop {
467	        match crossterm::event::poll(Duration::from_millis(100)) {
468	            Ok(true) => {
469	                if let Ok(crossterm::event::Event::Key(key)) = crossterm::event::read() {
470	                    if tx_key.blocking_send(AppEvent::Key(key)).is_err() { break; }
471	                }
472	            }
473	            Ok(false) => {}
474	            Err(_) => break,
475	        }
476	    });
477	
478	    // Tick timer
479	    let tx_tick = tx.clone();
480	    tokio::spawn(async move {
481	        loop {
482	            tokio::time::sleep(Duration::from_millis(100)).await;
483	            if tx_tick.send(AppEvent::Tick).await.is_err() { break; }
484	        }
485	    });
486	
487	    loop {
488	        terminal.draw(|f| ui::render(f, &mut app))?;
489	        match rx.recv().await {
490	            Some(AppEvent::Baro(ev)) => {
491	                // Fire notification immediately when stories complete
492	                if matches!(ev, BaroEvent::NotificationReady) {
493	                    notification::notify_completion();
494	                }
495	                let story_start_id = if let BaroEvent::StoryStart { ref id, .. } = ev {
496	                    Some(id.clone())
497	                } else {
498	                    None
499	                };
500	                app.handle_event(ev);
501	                if story_start_id.is_some() {
502	                    app.auto_scroll_to_running();
503	                }
504	                if let Some(ref sid) = story_start_id {
505	                    if app.global_tab == app::GlobalTab::Dag {
506	                        let visible = terminal.size().map(|s| s.height.saturating_sub(10)).unwrap_or(20);
507	                        app.dag_auto_scroll_to_story(sid, visible);
508	                    }
509	                }
510	            }
511	            Some(AppEvent::ContextReady(content)) => {
512	                app.claude_md_content = Some(content);
513	                app.start_planning();
514	                spawn_planner(&app, &cwd, tx.clone());
515	            }
516	            Some(AppEvent::ContextError(err)) => {
517	                app.planning_error = Some(err);
518	            }
519	            Some(AppEvent::PlanReady(stories, project, branch, description)) => {
520	                app.project = project;
521	                app.branch_name = branch;
522	                app.description = description;
523	                app.show_review(stories);
524	            }
525	            Some(AppEvent::PlanError(err)) => {
526	                app.planning_error = Some(err);
527	            }
528	            Some(AppEvent::RefineReady(stories, project, branch, description)) => {
529	                app.refining = false;
530	                app.project = project;
531	                app.branch_name = branch;
532	                app.description = description;
533	                app.show_review(stories);
534	            }
535	            Some(AppEvent::RefineError(err)) => {
536	                app.refining = false;
537	                app.planning_error = Some(err);
538	            }
539	            Some(AppEvent::BranchError(err)) => {
540	                app.planning_error = Some(err);
541	                app.screen = Screen::Review;
542	            }
543	            Some(AppEvent::Key(key)) => {
544	                use crossterm::event::{KeyCode, KeyEventKind, KeyModifiers};
545	                if key.kind != KeyEventKind::Press {
546	                    continue;
547	                }
548	
549	                // Clear dock badge when user returns to the terminal after a notification
550	                if app.notification_ready {
551	                    notification::clear_badge();
552	                }
553	
554	                match app.screen {
555	                    Screen::Welcome => match key.code {
556	                        KeyCode::Esc => return Ok(()),
557	                        KeyCode::Tab => { app.welcome_field = app.welcome_field.next(); }
558	                        KeyCode::BackTab => { app.welcome_field = app.welcome_field.prev(); }
559	                        KeyCode::Enter => {
560	                            if app.welcome_field != app::WelcomeField::Goal {
561	                                // Enter on non-goal fields = jump to goal
562	                                app.welcome_field = app::WelcomeField::Goal;
563	                            } else if !app.goal_input.is_empty() {
564	                                if app.skip_context {
565	                                    app.start_planning();
566	                                    spawn_planner(&app, &cwd, tx.clone());
567	                                } else {
568	                                    let claude_md_path = cwd.join("CLAUDE.md");
569	                                    if claude_md_path.exists() {
570	                                        if let Ok(content) = std::fs::read_to_string(&claude_md_path) {
571	                                            app.claude_md_content = Some(content);
572	                                        }
573	                                        app.start_planning();
574	                                        spawn_planner(&app, &cwd, tx.clone());
575	                                    } else {
576	                                        app.start_context();
577	                                        spawn_context_builder(&cwd, tx.clone());
578	                                    }
579	                                }
580	                            }
581	                        }
582	                        KeyCode::Left | KeyCode::Right => {
583	                            match app.welcome_field {
584	                                app::WelcomeField::Model => {
585	                                    // Cycle: routed -> opus -> sonnet -> haiku
586	                                    let options: &[Option<&str>] = &[None, Some("opus"), Some("sonnet"), Some("haiku")];
587	                                    let current = options.iter().position(|o| {
588	                                        match (&app.override_model, o) {
589	                                            (None, None) => app.model_routing,
590	                                            (Some(m), Some(o)) => m.as_str() == *o,
591	                                            _ => false,
592	                                        }
593	                                    }).unwrap_or(0);
594	                                    let next = if key.code == KeyCode::Right {
595	                                        (current + 1) % options.len()
596	                                    } else {
597	                                        (current + options.len() - 1) % options.len()
598	                                    };
599	                                    if next == 0 {
600	                                        app.override_model = None;
601	                                        app.model_routing = true;
602	                                    } else {
603	                                        app.override_model = options[next].map(|s| s.to_string());
604	                                        app.model_routing = false;
605	                                    }
606	                                }
607	                                app::WelcomeField::Parallel => {
608	                                    if key.code == KeyCode::Right {
609	                                        app.parallel_limit = app.parallel_limit.saturating_add(1);
610	                                    } else {
611	                                        app.parallel_limit = app.parallel_limit.saturating_sub(1);
612	                                    }
613	                                }
614	                                app::WelcomeField::Timeout => {
615	                                    if key.code == KeyCode::Right {
616	                                        app.timeout_secs = (app.timeout_secs + 60).min(3600);
