891	fn spawn_planner(app: &App, cwd: &Path, tx: mpsc::Sender<AppEvent>) {
892	    let goal = app.goal_input.clone();
893	    let planner = app.planner;
894	    let cwd = cwd.to_path_buf();
895	    let model = app.model_for_phase("planning");
896	    let context = app.claude_md_content.clone();
897	
898	    tokio::spawn(async move {
899	        let result = match planner {
900	            Planner::Claude => run_claude_planner(&goal, &cwd, model.as_deref(), context.as_deref()).await,
901	            Planner::OpenAI => run_openai_planner(&goal, &cwd).await,
902	        };
903	
904	        match result {
905	            Ok((stories, project, branch, description)) => {
906	                let _ = tx.send(AppEvent::PlanReady(stories, project, branch, description)).await;
907	            }
908	            Err(e) => {
909	                let _ = tx.send(AppEvent::PlanError(e.to_string())).await;
910	            }
911	        }
912	    });
913	}
