934	fn spawn_refiner(app: &App, feedback: &str, cwd: &Path, tx: mpsc::Sender<AppEvent>) {
935	    let feedback = feedback.to_string();
936	    let cwd = cwd.to_path_buf();
937	    let model = app.model_for_phase("planning");
938	    let context = app.claude_md_content.clone();
939	
940	    // Build current plan JSON from app state
941	    let stories_json: Vec<serde_json::Value> = app.review_stories.iter().map(|s| {
942	        serde_json::json!({
943	            "id": s.id,
944	            "title": s.title,
945	            "description": s.description,
946	            "dependsOn": s.depends_on,
947	        })
948	    }).collect();
949	    let plan_json = serde_json::json!({
950	        "project": app.project,
951	        "branchName": app.branch_name,
952	        "description": app.description,
953	        "userStories": stories_json,
954	    });
955	    let plan_str = serde_json::to_string_pretty(&plan_json).unwrap_or_default();
956	
957	    tokio::spawn(async move {
958	        let base_prompt = format!(
959	            "Here is the current plan:\n{}\nThe user wants these changes: {}\nGenerate an updated plan with the same JSON schema. Keep stories the user did not mention unchanged. Output ONLY valid JSON, no markdown, no explanation.",
960	            plan_str, feedback
961	        );
962	        let prompt = match context {
963	            Some(ctx) => format!("Here is the project context:\n{}\n\n{}", ctx, base_prompt),
964	            None => base_prompt,
965	        };
966	
967	        let result = async {
968	            let config = claude_runner::ClaudeRunConfig {
969	                prompt: prompt.clone(),
970	                cwd: cwd.clone(),
971	                model: model.clone(),
972	            };
973	
974	            let output = claude_runner::spawn_claude_json(&config).await?;
975	
976	            let claude_output: serde_json::Value = serde_json::from_str(&output.stdout)
977	                .map_err(|e| format!("Failed to parse Claude JSON wrapper: {}", e))?;
978	
979	            let plan_text = claude_output
980	                .get("result")
981	                .and_then(|v| v.as_str())
982	                .unwrap_or(&output.stdout);
983	
984	            let json_str = extract_json(plan_text);
985	
986	            let prd: PrdOutput = serde_json::from_str(&json_str)
987	                .map_err(|e| format!("Failed to parse refined PRD JSON: {}\nRaw: {}", e, &json_str[..json_str.len().min(500)]))?;
988	
989	            let stories: Vec<ReviewStory> = prd.user_stories
990	                .into_iter()
991	                .map(|s| ReviewStory {
992	                    id: s.id,
993	                    title: s.title,
994	                    description: s.description,
995	                    depends_on: s.depends_on,
996	                    completed: false,
997	                    model: s.model,
998	                })
999	                .collect();
1000	
1001	            Ok::<_, Box<dyn std::error::Error + Send + Sync>>((stories, prd.project, prd.branch_name, prd.description))
1002	        }.await;
1003	
1004	        match result {
1005	            Ok((stories, project, branch, description)) => {
1006	                let _ = tx.send(AppEvent::RefineReady(stories, project, branch, description)).await;
1007	            }
1008	            Err(e) => {
1009	                let _ = tx.send(AppEvent::RefineError(e.to_string())).await;
1010	            }
1011	        }
1012	    });
1013	}
