1015	fn spawn_executor(
1016	    _prd: executor::PrdFile,
1017	    cwd: PathBuf,
1018	    tx: mpsc::Sender<AppEvent>,
1019	    config: executor::ExecutorConfig,
1020	) {
1021	    // The orchestrator (TS, Mozaik-based) replaces the in-process Rust
1022	    // executor. Bridge BaroEvent → AppEvent::Baro the same way the old
1023	    // executor did so app/screens stay untouched.
1024	    let (exec_tx, mut exec_rx) = mpsc::channel::<BaroEvent>(256);
1025	
1026	    let tx_fwd = tx.clone();
1027	    tokio::spawn(async move {
1028	        while let Some(ev) = exec_rx.recv().await {
1029	            if tx_fwd.send(AppEvent::Baro(ev)).await.is_err() {
1030	                break;
1031	            }
1032	        }
1033	    });
1034	
1035	    let default_model = if config.model_routing {
1036	        Some("opus".to_string())
1037	    } else {
1038	        Some("opus".to_string())
1039	    };
1040	
1041	    // Default audit log path: ~/.baro/runs/<project>-<unix-secs>.jsonl.
1042	    // Living under the user's home directory (not the project's <cwd>/.baro/)
1043	    // means the diagnostic trail survives anything that touches the
1044	    // project working tree: git checkouts, branch switches, manual
1045	    // cleanups, IDE indexers — none of those reach into ~. We had a
1046	    // run where 495 KB of audit data vanished from <cwd>/.baro/runs/
1047	    // between the run ending and the user kill; we still don't know
1048	    // what wiped it, but moving the file out of the project dir means
1049	    // we don't have to find out.
1050	    //
1051	    // Always-on so post-mortems on stuck/abnormal runs are possible
1052	    // without rerunning. We pre-touch BOTH the audit JSONL and the
1053	    // stderr.txt sidecar before spawning the orchestrator so the
1054	    // diagnostic surface exists even if the JS process explodes inside
1055	    // its first 50ms.
1056	    let project_name = cwd
1057	        .file_name()
1058	        .and_then(|n| n.to_str())
1059	        .map(|s| s.replace(['/', ' ', '\t', '\n'], "_"))
1060	        .unwrap_or_else(|| "project".to_string());
1061	    let unix_secs = std::time::SystemTime::now()
1062	        .duration_since(std::time::UNIX_EPOCH)
1063	        .map(|d| d.as_secs())
1064	        .unwrap_or(0);
1065	    let audit_root = std::env::var_os("HOME")
1066	        .map(PathBuf::from)
1067	        .unwrap_or_else(|| cwd.clone())
1068	        .join(".baro")
1069	        .join("runs");
1070	    let audit_log_default =
1071	        audit_root.join(format!("{}-{}.jsonl", project_name, unix_secs));
1072	    if let Some(parent) = audit_log_default.parent() {
1073	        if let Err(e) = std::fs::create_dir_all(parent) {
1074	            eprintln!(
1075	                "[baro] warning: could not create audit dir {}: {}",
1076	                parent.display(),
1077	                e
1078	            );
1079	        }
1080	    }
1081	    // Pre-touch the JSONL so external watchers (and our own diagnostics)
1082	    // can rely on the file existing even before the Auditor opens it.
1083	    if let Err(e) = std::fs::OpenOptions::new()
1084	        .create(true)
1085	        .append(true)
1086	        .open(&audit_log_default)
1087	    {
1088	        eprintln!(
1089	            "[baro] warning: could not touch audit log {}: {}",
1090	            audit_log_default.display(),
1091	            e
1092	        );
1093	    }
1094	    // Pre-touch the stderr sidecar for the same reason.
1095	    let stderr_sidecar = audit_log_default.with_extension("stderr.txt");
1096	    if let Err(e) = std::fs::OpenOptions::new()
1097	        .create(true)
1098	        .append(true)
1099	        .open(&stderr_sidecar)
1100	    {
1101	        eprintln!(
1102	            "[baro] warning: could not touch stderr sidecar {}: {}",
1103	            stderr_sidecar.display(),
1104	            e
1105	        );
1106	    }
1107	
1108	    let orch_cfg = orchestrator_client::OrchestratorConfig {
1109	        prd_path: cwd.join("prd.json"),
1110	        cwd,
1111	        parallel: config.parallel,
1112	        timeout_secs: config.timeout_secs,
1113	        override_model: config.override_model,
1114	        default_model,
1115	        skip_git: false,
1116	        audit_log: Some(audit_log_default),
1117	        with_critic: config.with_critic,
1118	        critic_model: config.critic_model,
1119	        with_librarian: config.with_librarian,
1120	        with_sentry: config.with_sentry,
1121	        with_surgeon: config.with_surgeon,
1122	        surgeon_use_llm: config.surgeon_use_llm,
1123	        surgeon_model: config.surgeon_model,
1124	    };
