1129	    let base_prompt = format!("{}\n\nUser goal: {}", CLAUDE_PLANNER_PROMPT, goal);
1130	    let prompt = match context {
1131	        Some(ctx) => format!("Here is the project context:\n{}\n\n{}", ctx, base_prompt),
1132	        None => base_prompt,
1133	    };
1134	
1135	    let config = claude_runner::ClaudeRunConfig {
1136	        prompt,
1137	        cwd: cwd.to_path_buf(),
1138	        model: model.map(|s| s.to_string()),
1139	    };
