1144	    let claude_output: serde_json::Value = serde_json::from_str(&output.stdout)
1145	        .map_err(|e| format!("Failed to parse Claude JSON wrapper: {}", e))?;
1146	
1147	    // The actual plan JSON is in the "result" field as a text string
1148	    let plan_text = claude_output
1149	        .get("result")
