1	/**
2	 * Operator — bridge from external user-input commands (Rust TUI today,
3	 * web UI later) to the Mozaik bus. The Operator joins the environment
4	 * but only emits on demand: callers invoke `dispatch(cmd)` when a
5	 * command arrives over the TUI protocol, and Operator translates it
6	 * into bus events.
7	 *
8	 * Library-grade: knows nothing about TUI specifics, only about the
9	 * canonical command shape and how to express it as ContextItems.
10	 */
11	
12	import {
13	    AgenticEnvironment,
14	    ContextItem,
15	    Participant,
16	} from "@mozaik-ai/core"
17	
18	import { AgentTargetedMessageItem } from "../types.js"
19	
20	export type OperatorCommand =
21	    | { kind: "redirect"; storyId: string; message: string }
22	    | { kind: "abort"; storyId: string }
23	    | { kind: "abort_all" }
24	    | { kind: "shutdown" }
25	
26	export interface OperatorHooks {
27	    /** Called when an `abort` command arrives. */
28	    onAbort?: (storyId: string) => void
29	    /** Called when `abort_all` arrives. */
30	    onAbortAll?: () => void
31	    /** Called when `shutdown` arrives. */
32	    onShutdown?: () => void
33	}
34	
35	export class Operator extends Participant {
36	    private envRef: AgenticEnvironment | null = null
37	
38	    constructor(private readonly hooks: OperatorHooks = {}) {
39	        super()
40	    }
41	
42	    setEnvironment(env: AgenticEnvironment): void {
43	        this.envRef = env
44	    }
45	
46	    async onContextItem(): Promise<void> {
47	        // Operator is push-only: it emits in response to external
48	        // commands, never reacts to bus events.
49	    }
50	
51	    /** Translate an external command into bus action / hook callback. */
52	    dispatch(cmd: OperatorCommand): void {
53	        switch (cmd.kind) {
54	            case "redirect": {
55	                this.emit(
56	                    new AgentTargetedMessageItem(cmd.storyId, cmd.message, {
57	                        source: "operator",
58	                    }),
59	                )
60	                return
61	            }
62	            case "abort": {
63	                this.hooks.onAbort?.(cmd.storyId)
64	                return
65	            }
66	            case "abort_all": {
67	                this.hooks.onAbortAll?.()
68	                return
69	            }
70	            case "shutdown": {
71	                this.hooks.onShutdown?.()
72	                return
73	            }
74	        }
75	    }
76	
77	    private emit(item: ContextItem): void {
78	        this.envRef?.deliverContextItem(this, item)
79	    }
80	}
